// FAIL-CLOSED per-entity: WF5 Parse Scores (quarantine on malformed, no whole-job throw)
const item = $input.first();
const loopNode = $('Loop Entities');
const entity = (loopNode && loopNode.item && loopNode.item.json) ? loopNode.item.json : (item && item.json) ? item.json : {};
const jobId = entity.job_id || (($('Set Job Vars').first().json || {}).job_id) || 'unknown';
const sd = $getWorkflowStaticData('global');
const totalKey = 'wf5_total_' + jobId;
const qualKey = 'wf5_qualified_' + jobId;
const quarKey = 'wf5_quarantined_' + jobId;
sd[totalKey] = (sd[totalKey] || 0) + 1;

function quarantine(reason) {
  sd[quarKey] = (sd[quarKey] || 0) + 1;
  return [{ json: Object.assign({}, entity, { status: 'quarantined', score_error: reason }) }];
}

if (!item || !item.json) {
  return quarantine('WF5_LLM_RESPONSE_INVALID:no input');
}
const rawResponse = item.json;
if (!rawResponse.choices || !Array.isArray(rawResponse.choices) || rawResponse.choices.length === 0) {
  return quarantine('WF5_LLM_RESPONSE_INVALID:choices absent or empty');
}
const content = rawResponse.choices[0]?.message?.content;
if (!content || typeof content !== 'string' || content.trim() === '') {
  return quarantine('WF5_LLM_RESPONSE_INVALID:content empty');
}
let p;
try {
  const clean = content.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  p = JSON.parse(clean);
} catch(e) {
  return quarantine('WF5_LLM_RESPONSE_INVALID:JSON parse failed');
}
const scoreFields = ['relevance_score', 'freshness_score', 'solvency_score', 'contactability_score'];
for (let i = 0; i < scoreFields.length; i++) {
  const f = scoreFields[i];
  const val = p[f];
  if (val === undefined || val === null) return quarantine('WF5_LLM_RESPONSE_INVALID:missing ' + f);
  const num = Number(val);
  if (!isFinite(num)) return quarantine('WF5_LLM_RESPONSE_INVALID:not finite ' + f);
  if (num < 0 || num > 100) return quarantine('WF5_LLM_RESPONSE_INVALID:out of range ' + f);
}
const rel = Number(p.relevance_score) || 0;
const fresh = Number(p.freshness_score) || 0;
const sol = Number(p.solvency_score) || 0;
const con = Number(p.contactability_score) || 0;
const total = Math.round(0.35 * rel + 0.20 * fresh + 0.25 * sol + 0.20 * con);
const status = total >= 60 ? 'qualified' : 'new';
if (status === 'qualified') { sd[qualKey] = (sd[qualKey] || 0) + 1; }
return [{ json: { ...entity, relevance_score: rel, freshness_score: fresh, solvency_score: sol, contactability_score: con, total_score: total, matched_service: p.matched_service || '', why_relevant: p.why_relevant || '', recommended_action: p.recommended_action || '', first_message_draft: p.first_message_draft || '', status: status } }];

const jobId = $('Set Job Vars').first().json.job_id || '';
const entityType = $('Set Job Vars').first().json.entity_type || 'lead';
if (!jobId) throw new Error('Prepare Report Trigger: job_id missing');
const sd = $getWorkflowStaticData('global');
const total = sd['wf5_total_' + jobId] || 0;
const quarantined = sd['wf5_quarantined_' + jobId] || 0;
const qualified = sd['wf5_qualified_' + jobId] || 0;
if (total > 0 && quarantined >= total) {
  throw new Error('WF5_SCORING_TOTAL_OUTAGE');
}
return [{ json: {
  job_id: jobId,
  entity_type: entityType,
  result_mode: 'scored',
  accepted_count: $('Set Job Vars').first().json.accepted_count || 0,
  requested_count: $('Set Job Vars').first().json.requested_count,
  qualified_count: qualified
} }];

const jobId = $('Set Job Vars').first().json.job_id || '';
const entityType = $('Set Job Vars').first().json.entity_type || 'lead';
if (!jobId) throw new Error('Prepare No Results: job_id missing');
return [{ json: {
  job_id: jobId,
  entity_type: entityType,
  result_mode: 'no_results',
  accepted_count: $('Set Job Vars').first().json.accepted_count || 0,
  requested_count: $('Set Job Vars').first().json.requested_count,
  qualified_count: 0
} }];
